    this._pendingLevelIds = new Set(opts.levelIds);
    this._totalElementCount = opts.totalElementCount;
    this._skipRedetectRooms = opts.skipRedetectRooms ?? false;
    this._skipPbrUpgrade = opts.skipPbrUpgrade ?? false;
    if (!this._skipPbrUpgrade) {
      let _sceneMeshes = -1;
      try {
        _sceneMeshes = this._sceneMeshCountProvider?.() ?? -1;
      } catch {
        _sceneMeshes = -1;
      }
      const _expected = opts.totalElementCount;
      if (_sceneMeshes > BatchCoordinatorImpl.LARGE_BATCH_SKIP_PBR_SCENE_MESHES || _expected > BatchCoordinatorImpl.LARGE_BATCH_SKIP_PBR_ELEMENTS) {
        this._skipPbrUpgrade = true;
        console.log(
          `[BatchCoordinator] §PERF-LARGE-BATCH-SKIP-PBR auto-enabled skipPbrUpgrade (sceneMeshes=${_sceneMeshes}, expectedElements=${_expected}) — skipping the cosmetic whole-scene PBR upgrade for this large batch.`
        );
      }
    }
    this._registrationQueue = [];
    this._postBatchWindowEvents.clear();
    if (this._regDrainDispose !== null) {
      this._regDrainDispose();
      this._regDrainDispose = null;
    }
